def validate_items(items):
    for item in items:
        if item['price'] < 0 or item['quantity'] < 0:
            raise ValueError("Item price or quantity cannot be negative.")

def calculate_pricing(items, is_vip=False):
    subtotal = sum(item['price'] * item['quantity'] for item in items)
    discount = 0.10 if is_vip else 0  # 10% discount for VIP customers
    discounted_total = subtotal * (1 - discount)
    total_with_tax = discounted_total * 1.07  # Assuming 7% tax
    return round(total_with_tax, 2)

def format_receipt(items, total):
    receipt = "Order Receipt:\n"
    for item in items:
        receipt += f"Item: {item['name']}, Quantity: {item['quantity']}, Price: ${item['price']:.2f}\n"
    receipt += f"Subtotal: ${sum(item['price'] * item['quantity'] for item in items):.2f}\n"
    receipt += f"Total (including tax): ${total:.2f}\n"
    return receipt

def process_order(items, is_vip=False):
    validate_items(items)
    total = calculate_pricing(items, is_vip)
    receipt = format_receipt(items, total)
    return {"total": total, "receipt": receipt}
